//! Single-response streaming keeps each representation atomic; no synthetic
//! Range stitching or strong-ETag requirement is needed.
use axum::{
    body::Bytes,
    http::{HeaderMap, StatusCode},
};
use futures_util::Stream;
use std::{io, pin::Pin};
pub(crate) struct Download {
    pub status: StatusCode,
    pub headers: HeaderMap,
    pub url: url::Url,
    pub body: Pin<Box<dyn Stream<Item = Result<Bytes, io::Error>> + Send>>,
}
/// Deliberately accept only one finite/open/suffix byte range. Multipart ranges
/// are not generated by the player and would complicate bounded delivery.
pub(crate) fn valid_range(raw: &str) -> bool {
    if raw.len() > 100 {
        return false;
    }
    let Some((start, end)) = raw.strip_prefix("bytes=").and_then(|s| s.split_once('-')) else {
        return false;
    };
    let decimal = |s: &str| -> Option<u64> {
        if s.is_empty() || !s.bytes().all(|b| b.is_ascii_digit()) {
            return None;
        }
        s.parse().ok()
    };
    if start.is_empty() {
        return decimal(end).is_some_and(|v| v > 0);
    }
    decimal(start)
        .is_some_and(|start| end.is_empty() || decimal(end).is_some_and(|end| end >= start))
}
#[cfg(test)]
mod tests {
    use super::*;
    #[test]
    fn accepts_single_ranges_and_rejects_ambiguous_or_overflowing_input() {
        for raw in ["bytes=0-", "bytes=12-99", "bytes=-1024", "bytes=0-0"] {
            assert!(valid_range(raw), "{raw}");
        }
        for raw in [
            "bytes=-0",
            "bytes=9-3",
            "bytes=0-1,3-4",
            "bytes=+1-3",
            "bytes= 0-1",
            "bytes=18446744073709551616-",
            "bytes=-",
            "items=0-1",
        ] {
            assert!(!valid_range(raw), "{raw}");
        }
    }
}
